    if(name==null||descriptor==null){
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    synchronized (this) {
        // Search for an existing entry
        for (int i = 0; i < constantPool.size(); i++) {
            Object entry = constantPool.get(i);
            if (entry instanceof ConstantNameAndTypeInfo) {
                ConstantNameAndTypeInfo info = (ConstantNameAndTypeInfo) entry;
                if (name.equals(info.getName()) && descriptor.equals(info.getDescriptor())) {
                    return i; // already present
                }
            }
        }
        // Not found, create and add new entry
        ConstantNameAndTypeInfo newInfo = new ConstantNameAndTypeInfo(name, descriptor);
        constantPool.add(newInfo);
        return constantPool.size() - 1; // index of new entry
    }
}

