public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return;
    }
    Deque<Object[]> stack = new ArrayDeque<>();
    // Each entry: [current file, processed flag]
    stack.push(new Object[] { file, Boolean.FALSE });
    while (!stack.isEmpty()) {
        Object[] top = stack.pop();
        File current = (File) top[0];
        boolean processed = (Boolean) top[1];
        if (!processed) {
            // Mark as processed after children
            stack.push(new Object[] { current, Boolean.TRUE });
            if (current.isDirectory()) {
                File[] children = current.listFiles();
                if (children != null) {
                    for (File child : children) {
                        stack.push(new Object[] { child, Boolean.FALSE });
                    }
                }
            }
        } else {
            current.deleteOnExit();
        }
    }
}

