private String buildContentRange() {
    // Build the HTTP 'Content-Range' header value
    // The typical format is: "bytes start-end/total"
    // Assumes that the class contains the fields:
    //   long rangeStart, rangeEnd, contentLength
    long start = this.rangeStart;
    long end   = this.rangeEnd;
    long total = this.contentLength;

    // If total length is unknown, use '*'
    String totalStr = (total >= 0) ? Long.toString(total) : "*";

    // Construct the header value
    return String.format("bytes %d-%d/%s", start, end, totalStr);
}

