private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    // If the source list is empty, nothing to move
    if (list.head == null) {
        return;
    }

    // Preserve the size of the source list
    int movedSize = list.size;

    // If the current list is not empty, append the source list after the current tail
    if (this.tail != null) {
        this.tail.next = list.head;     // link current tail to the head of source list
        list.head.prev = this.tail;     // link source head back to current tail
        this.tail = list.tail;          // new tail is the old tail of the source list
    } else { // current list is empty
        // Just adopt the source list's head and tail
        this.head = list.head;
        this.tail = list.tail;
    }

    // Update the size of this list
    this.size += movedSize;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

