private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        return null;
    }
    // Create a circulator starting at the given node in the requested direction
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    // If the starting node already satisfies the predicate, we can immediately return it
    if (predicate.test(circulator.getNode())) {
        return circulator;
    }
    // Traverse until we reach the stop node or loop back to the start
    // The loop guards against infinite cycles by checking the start node again
    Node currentNode = circulator.getNode();
    while (!currentNode.equals(stop) && !currentNode.equals(start)) {
        circulator.next();
        currentNode = circulator.getNode();
        if (predicate.test(currentNode)) {
            return circulator;
        }
    }
    // If we exit the loop, either the stop node was reached or we completed a full cycle.
    // Return the circulator positioned at the last examined node (stop or start).
    return circulator;
}

