Edge edgeToNext() {
    try {
        // Retrieve the nodes that were returned in the previous call
        // and the one that will be returned next.
        Node prev = this.previousNode;   // node that was returned last
        Node next = this.nextNode;       // node that will be returned next

        // If either reference is missing, there is no edge to return.
        if (prev == null || next == null) {
            return null;
        }

        // If either node is virtual, use its real counterpart.
        if (prev.isVirtual()) {
            prev = prev.getRealNode();
        }
        if (next.isVirtual()) {
            next = next.getRealNode();
        }

        // Return the edge that connects the real nodes.
        return prev.getEdgeTo(next);
    } catch (Exception e) {
        // Any runtime exception should be swallowed and a null
        // value returned, signalling that no edge could be produced.
        return null;
    }
}

