protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }
    // Count how many times each vertex appears as a target
    Map<V, Integer> targetCount = new HashMap<>();
    for (E e : tour) {
        V target = graph.getEdgeTarget(e);
        targetCount.merge(target, 1, Integer::sum);
    }
    // Find a vertex that never appears as a target – the likely start of the tour
    V start = null;
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        if (!targetCount.containsKey(src)) {
            start = src;
            break;
        }
    }
    if (start == null) {
        return null; // cannot determine a start vertex
    }
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> used = new HashSet<>();
    V current = start;
    vertices.add(current);
    // Walk through the edge set constructing the path
    while (true) {
        boolean progressed = false;
        for (E e : tour) {
            if (used.contains(e)) {
                continue;
            }
            if (graph.getEdgeSource(e).equals(current)) {
                edges.add(e);
                current = graph.getEdgeTarget(e);
                vertices.add(current);
                used.add(e);
                progressed = true;
                break;
            }
        }
        if (!progressed) {
            break;
        }
    }
    // Return the constructed path (weight is set to 0.0)
    return new GraphPathImpl<>(graph, start, current, edges, 0);
}

