    if (tour == null) {
        throw new IllegalArgumentException("tour must not be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, Collections.emptyList(), Collections.emptyList(), 0.0);
    }
    // Map to count vertex degrees in the tour
    Map<V,Integer> vertexDeg = new HashMap<>();
    // Adjacency map: vertex -> edges incident to it
    Map<V,Set<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        vertexDeg.put(src, vertexDeg.getOrDefault(src, 0) + 1);
        vertexDeg.put(tgt, vertexDeg.getOrDefault(tgt, 0) + 1);
        adjacency.computeIfAbsent(src, k -> new HashSet<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new HashSet<>()).add(e);
    }
    // Choose start vertex: vertex of degree 1 if exists, otherwise arbitrary
    V start = null;
    for (Map.Entry<V,Integer> entry : vertexDeg.entrySet()) {
        if (entry.getValue() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        start = adjacency.keySet().iterator().next();
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    vertexList.add(start);
    V current = start;
    while (visitedEdges.size() < tour.size()) {
        Set<E> edges = adjacency.get(current);
        if (edges == null) {
            break;
        }
        boolean found = false;
        for (E e : edges) {
            if (!visitedEdges.contains(e)) {
                visitedEdges.add(e);
                edgeList.add(e);
                V next = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
                vertexList.add(next);
                current = next;
                found = true;
                break;
