private void check(String modelName) throws IllegalStateException {
    // Retrieve sharding key indices for the given model.
    // The actual retrieval mechanism depends on your application's metadata storage.
    java.util.List<Integer> indices = getShardingKeyIndices(modelName);
    if (indices == null || indices.isEmpty()) {
        // Nothing to verify if there are no sharding keys.
        return;
    }
    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;
    for (int idx : indices) {
        if (idx < min) {
            min = idx;
        }
        if (idx > max) {
            max = idx;
        }
    }
    // For a continuous sequence from min to max, the number of indices
    // must equal max - min + 1.
    if (indices.size() != (max - min + 1)) {
        throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
    }
}

