static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Validate month
        if (month < 1 || month > 12) {
            return timeBucket;
        }

        // Determine days in the month (consider leap years for February)
        int daysInMonth = 31;
        switch (month) {
            case 4: case 6: case 9: case 11:
                daysInMonth = 30;
                break;
            case 2:
                boolean leap = ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0));
                daysInMonth = leap ? 29 : 28;
                break;
            default:
                daysInMonth = 31;
                break;
        }

        // Validate day
        if (day < 1 || day > daysInMonth) {
            return timeBucket;
        }

        int bucketDay = day - ((day - 1) % dayStep);
        return year * 10000L + month * 100L + bucketDay;
    } catch (Exception e) {
        // In case of any unexpected error, fall back to original value
        return timeBucket;
    }
}

