public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    final int MAXIMUM_CAPACITY = 1 << 30; // maximum capacity for hash tables
    int candidate = Math.max(2, desiredCapacity);
    if (candidate > MAXIMUM_CAPACITY) {
        return MAXIMUM_CAPACITY;
    }
    // If desiredCapacity >= 1000, limit search to within 11% if possible
    if (candidate >= 1000) {
        long upperLong = candidate * 111L / 100 + 1; // within 11%
        if (upperLong > MAXIMUM_CAPACITY) {
            upperLong = MAXIMUM_CAPACITY;
        }
        int upper = (int) upperLong;
        for (int n = candidate; n <= upper; n++) {
            if (isPrime(n)) {
                return n;
            }
        }
        // If not found within 11%, continue searching beyond upper bound
        for (int n = upper + 1; n <= MAXIMUM_CAPACITY; n++) {
            if (isPrime(n)) {
                return n;
            }
        }
    } else {
        for (int n = candidate; n <= MAXIMUM_CAPACITY; n++) {
            if (isPrime(n)) {
                return n;
            }
        }
    }
    return MAXIMUM_CAPACITY;

    // Helper method to test primality
    boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if ((num & 1) == 0) return false;
        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
