    if (desiredCapacity <= 3) {
        return 3;
    }
    // Start searching from desiredCapacity
    int candidate = Math.max(desiredCapacity, 2);
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate++;
    }
}

